WITH filtered_customers AS (SELECT * FROM customers WHERE credit_limit < 5000 AND (name NOT LIKE '%Tayl%' OR city IN ('Chiang Mai', 'Berlin', 'Tokyo'))), customers_stats AS (SELECT QUARTER(signup_date) AS signup_quarter, country, MIN(age) AS min_age, SORT_ARRAY(COLLECT_SET(city)) AS city_list FROM filtered_customers GROUP BY QUARTER(signup_date), country) SELECT signup_quarter, country, min_age, city_list FROM customers_stats;
